<?php
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__).'/sms.php';method('POST');$u=current_user(true);$c=sms_config();$tel=sms_tel();$action=text_input('action',10);$code=text_input('code',8);rate('sms_bind',10,600);lock_user('binding',$u['uid']);
if($action==='unbind'){$old=one('SELECT uid,tel FROM '.table('comiis_sms_user').' WHERE uid=? AND tel=?',[$u['uid'],$tel]);if(!$old)respond(null,403,'手机号不属于当前用户');consume_sms($tel,3,$code,$c);exec_sql('DELETE FROM '.table('comiis_sms_user').' WHERE uid=? AND tel=?',[$u['uid'],$tel]);exec_sql('UPDATE '.table('common_member_profile').' SET mobile=? WHERE uid=?',['',$u['uid']]);}
elseif($action==='bind'){if(one('SELECT id FROM '.table('comiis_sms_user').' WHERE uid=? OR tel=?',[$u['uid'],$tel]))respond(null,422,'用户或手机号已绑定，请先解绑');consume_sms($tel,2,$code,$c);exec_sql('INSERT INTO '.table('comiis_sms_user').' (uid,tel,regip,type,state,dateline,province,ua) VALUES (?,?,?,0,2,?,?,?)',[$u['uid'],$tel,$_SERVER['REMOTE_ADDR'],time(),'APP',substr($_SERVER['HTTP_USER_AGENT']??'APP',0,250)]);exec_sql('UPDATE '.table('common_member_profile').' SET mobile=? WHERE uid=?',[$tel,$u['uid']]);}else respond(null,422,'操作无效');respond(user_public($u['uid'],true));
